from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD."""
    if yyyymmdd is None or yyyymmdd in ("", "00000000"):
        return None
    return f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:8]}"


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to the legacy YYYYMMDD format."""
    if iso is None or iso == "":
        return "00000000"
    return f"{iso[:4]}{iso[5:7]}{iso[8:10]}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N flag to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a decimal amount to integer currency minor units."""
    if amount is None or (isinstance(amount, str) and amount.strip() == ""):
        return 0

    currency_code = "USD" if currency is None or currency.strip() == "" else currency
    exponent = 0 if currency_code.upper() == "JPY" else 2
    value = Decimal(str(amount))
    scale = Decimal(10) ** exponent
    return int((value * scale).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
